pageFunction:
// Runs on every page and returns its title and main text.
// To scrape another site, change the Start URL. To extract other data, edit this
// function; the README lists everything on the "context" object.
async function pageFunction(context) {
    // jQuery reads the page (needs "Inject jQuery", which is on by default).
    const $ = context.jQuery;
    const pageTitle = $('title').first().text().replace(/\s+/g, ' ').trim();

    // The main content: the page's <main> or role="main" area, a single <article>,
    // a common content container, or else the whole body.
    let main = $('main, [role="main"]').first();
    if (!main.length && $('article').length === 1) main = $('article');
    if (!main.length) main = $('#content, #main, #main-content, .main-content, .post-content, .entry-content').first();
    if (!main.length) main = $('body');

    // Work on a copy without menus, headers, footers, sidebars, forms and scripts.
    main = main.clone();
    main.find('nav, header, footer, aside, form, script, style, noscript, template, svg, iframe, button, '
        + '[role="navigation"], [role="banner"], [role="contentinfo"], [role="search"], [aria-hidden="true"], .headerlink').remove();
    // Mark the end of each block element, so paragraphs become separate lines.
    const BREAK = '\uE000';
    main.find('p, div, section, li, h1, h2, h3, h4, h5, h6, pre, blockquote, tr, dt, dd, br').after(BREAK);
    const text = main.text()
        .split(BREAK)
        .map((line) => line.replace(/\s+/g, ' ').trim())
        .filter(Boolean)
        .join('\n');

    context.log.info(`URL: ${context.request.url}, TITLE: ${pageTitle}`);

    // Each returned object becomes one row of the dataset.
    return {
        url: context.request.url,
        pageTitle,
        text,
    };
}

